import squishtest
from interops.libraries.mosaiq.interactions.objects.mosaiq_department_browse import DepartmentBrowseObjects
from interops.libraries.desktop import decorators as deco
from interops.libraries.squish_actions.constants import MOSAIQ_APP_NAME
from interops.libraries.squish_actions import CommonActions

def __find_department_browse_window() -> bool:
    """Searches for the department browse window. Returns True if successfully located.

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(DepartmentBrowseObjects.department_Browse_Window) is not None else False

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def choose_department_s(which_department: int):
    """
    Choose a department listed.

    The arugment, which_department, is the option to select. 0, Global(All). 1, the first one, 2, the second one.
    """
    if __find_department_browse_window:
        squishtest.snooze(2)
        CommonActions.left_click_object(DepartmentBrowseObjects.unTag_All_Button)
        CommonActions.press_home_key()
        if which_department == 0:
            #Global(All)
            CommonActions.left_click_object(DepartmentBrowseObjects.tag_All_Button)
        elif which_department == 1:
            #1st one
            CommonActions.press_key_spacebar()
        elif which_department == 2:
            #2nd one
            CommonActions.press_key_down_arrow()
            CommonActions.press_key_spacebar()

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_department_s():
    """
    Confirm the selection of the department and close the window
    """
    if __find_department_browse_window:
        CommonActions.left_click_object(DepartmentBrowseObjects.select_Button)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def cancel_select_department_s():
    """
    Cancel the selection of department and close the window
    """
    if __find_department_browse_window:
        CommonActions.left_click_object(DepartmentBrowseObjects.cancel_Button)
